// Classify one call site by the sequence of hidden classes it observed.
// Re-seeing a class does NOT add a new shape.
function icState(shapes) {
  const seen = [];
  for (const s of shapes) {
    if (!seen.includes(s)) seen.push(s); // count distinct, arrival order
  }
  const n = seen.length;
  // TODO return the state from n using V8's thresholds:
  // 0 -> 'uninitialized', 1 -> 'monomorphic', 2..4 -> 'polymorphic', 5+ -> 'megamorphic'
  return '';
}

const sites = {
  getX: ['HC1', 'HC1', 'HC1', 'HC1'],          // one shape, re-seen
  getY: ['HC1', 'HC2', 'HC1', 'HC2', 'HC3'],   // three distinct
  getZ: ['HC1', 'HC2', 'HC3', 'HC4', 'HC5', 'HC6'], // six distinct
};

const out = [];
for (const name in sites) out.push(`${name}=${icState(sites[name])}`);
console.log(out.join(' '));
